import 'package:flutter/material.dart';import '../../../core/network/football_repository.dart';
class TransferIntelligenceScreen extends StatefulWidget{const TransferIntelligenceScreen({super.key});@override State<TransferIntelligenceScreen> createState()=>_TransferIntelligenceScreenState();}
class _TransferIntelligenceScreenState extends State<TransferIntelligenceScreen>{final repo=FootballRepository();String status='all';@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Transfer Intelligence')),body:FutureBuilder<Map<String,dynamic>>(future:repo.transferIntelligence(status:status),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final d=s.data!;final filters=List<String>.from(d['filters']??[]);final items=List<dynamic>.from(d['items']??[]);return ListView(padding:const EdgeInsets.all(12),children:[Wrap(spacing:8,children:filters.map((f)=>ChoiceChip(label:Text(f),selected:f==status,onSelected:(_){setState(()=>status=f);})).toList()),const SizedBox(height:10),...items.map((t)=>Card(child:ListTile(title:Text('${t['headline']??t['player']?['name']??'Transfer'}'),subtitle:Text('${t['from_team']?['name_en']??'-'} → ${t['to_team']?['name_en']??'-'}\n${t['source_name']??''}'),trailing:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Text('${t['status']??''}'),if(t['confidence']!=null)Text('${t['confidence']}%')]))))]);}));}
